paper = open('/home/user/gp-rarelink/data/literature/ssadh/fulltext_md/41089664.md', encoding='utf-8').read()
d = json.load(open('/home/user/gp-rarelink/data/extracted/ssadh/ow-ssadh/per_paper/41089664.json', encoding='utf-8'))
bad = 0
for tname, rows in d["tables"].items():
    for ri, row in enumerate(rows):
        for fname, cell in row.items():
            if isinstance(cell, dict) and "span" in cell:
                s = cell["span"]
                if s is None: continue
                if isinstance(s, str): s = [s]
                for q in s:
                    if q not in paper:
                        bad += 1
                        print("MISSING:", tname, ri, fname, repr(q))
print("missing spans:", bad)
print("counts:", {k: len(v) for k, v in d["tables"].items()})
print("individuals:", len(d["tables"]["individuals"]))
print("tnfaip3 flag:", d["reports_individuals_with_tnfaip3_variant"])
# field completeness
schema = json.load(open('/home/user/gp-rarelink/pipeline/extract/claude_code/schema_ssadh_v5.json', encoding='utf-8'))
for t in schema["tables"]:
    names = [f["name"] for f in t["fields"]]
    for row in d["tables"][t["name"]]:
        if list(row.keys()) != names:
            print("FIELD MISMATCH", t["name"], [n for n in names if n not in row], [k for k in row if k not in names])
# checklist coverage
cl = [r["checklist_feature"]["value"] for r in d["tables"]["phenotype_checklist"]]
print("checklist rows:", len(cl), "unique:", len(set(cl)))
